import { type Locator, type Page, expect } from '@playwright/test';
import { getContentFileFilesListUrl } from '@pulp-ui/sdk/file/content-files';
import { type PulpObject, type TestObjects } from './api';
import { title } from './sign-in';

// The steps of the Upload dialog of a repository's Content tab that the upload
// specs share. The files are generated by the spec and handed to the browser as
// buffers; no file of the machine is read.

export interface GeneratedFile {
  // the file name the browser reports
  name: string;
  buffer: Buffer;
  // the relative path the unit gets in the repository, for a plugin that asks
  path?: string;
}

export const MiB = 1024 * 1024;

// The Content tab of a repository, with its Upload button pressed.
export async function openUploadDialog(
  page: Page,
  repositoryName: string,
  plugin = 'file',
): Promise<Locator> {
  await page.goto(
    `${plugin}/repositories/${encodeURIComponent(repositoryName)}/content`,
  );
  await expect(title(page, repositoryName)).toBeVisible();
  await page.getByRole('button', { name: 'Upload', exact: true }).click();
  const dialog = page.getByRole('dialog');
  await expect(dialog).toContainText('Upload files');
  return dialog;
}

// Chooses the files in the dialog and sets the relative path of each.
export async function chooseFiles(
  dialog: Locator,
  files: GeneratedFile[],
): Promise<void> {
  await dialog.locator('input[type=file]').setInputFiles(
    files.map(({ name, buffer }) => ({
      name,
      mimeType: 'application/octet-stream',
      buffer,
    })),
  );
  for (const { name, path } of files) {
    if (path !== undefined) {
      await dialog.getByLabel(`Relative path of ${name}`).fill(path);
    }
  }
}

// The row of the dialog's table that belongs to a file.
export const fileRow = (dialog: Locator, name: string): Locator =>
  dialog.getByRole('row').filter({ hasText: name });

// The file content units a repository version holds, by path.
export async function versionPaths(
  objects: TestObjects,
  version: string,
): Promise<string[]> {
  const units = await objects.list(getContentFileFilesListUrl(), {
    repository_version: version,
    fields: 'pulp_href,relative_path',
  });
  return units.map(({ relative_path }) => String(relative_path)).sort();
}

// The number of upload objects the server holds.
export async function uploadCount(objects: TestObjects): Promise<number> {
  const page = await objects.get('/pulp/api/v3/uploads/?limit=1');
  return Number((page as PulpObject)['count']);
}

// The method and path of every request the page sends to the API, in order.
export function recordRequests(page: Page): string[] {
  const seen: string[] = [];
  page.on('request', (request) => {
    const { pathname } = new URL(request.url());
    if (pathname.startsWith('/pulp/api/')) {
      seen.push(`${request.method()} ${pathname}`);
    }
  });
  return seen;
}
